import subprocess, tempfile, os
# Test that file containing "null" etc works via TUI
def run_file(content, via='file'):
    import subprocess, tempfile, os
    if via=='file':
        with tempfile.NamedTemporaryFile(mode='w', suffix='.json', delete=False, dir='/tmp') as tf:
            tf.write(content)
            fname=tf.name
        args=['./executable', fname]
        try:
            proc=subprocess.Popen(args, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            out,err=proc.communicate(timeout=1.2)
            return None,out,err,fname
        except subprocess.TimeoutExpired:
            proc.kill()
            try:
                out,err=proc.communicate(timeout=0.5)
            except:
                out,err=b'',b''
            os.unlink(fname)
            return None,out,err,fname
        finally:
            try:
                os.unlink(fname)
            except:
                pass
    else:
        try:
            proc=subprocess.Popen(['./executable'], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            out,err=proc.communicate(input=content.encode(), timeout=1.2)
            return proc.returncode,out,err,None
        except subprocess.TimeoutExpired:
            proc.kill()
            try:
                out,err=proc.communicate(timeout=0.5)
            except:
                out,err=b'',b''
            return None,out,err,None

for c in ['{"a":1}', '[]', '{}', 'null', 'true', '"hi"', '123', '  ']:
    rc,out,err,fname=run_file(c, via='file')
    print("file content",repr(c),"timeout",rc is None,"err",repr(err[:80] if err else err))
    rc2,out2,err2,_=run_file(c, via='stdin')
    print(" stdin",repr(c),"rc",rc2,"err",repr(err2[:80] if err2 else err2))


