import subprocess

def run_stdin(inp):
    import subprocess
    try:
        proc=subprocess.Popen(['./executable'], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        out,err=proc.communicate(input=inp, timeout=1.2)
        return proc.returncode,out,err
    except subprocess.TimeoutExpired:
        proc.kill()
        try:
            out,err=proc.communicate(timeout=0.5)
        except:
            out,err=b'',b''
        return None,out,err

tests = [
    (b'{"a":1}\n{"b":2}', b'\n[json.exception.parse_error.101]'),
    (b'{"a":1} // comment', None),
    (b'{"a":1 /* comment */}', None),
    (b'\xef\xbb\xbf{"a":1}', None), # BOM
    (b'{"a": "\u2603"}', None),
]

for inp, expect in tests:
    rc,out,err=run_stdin(inp)
    print(inp[:30], "rc",rc, "err",repr(err[:120] if err else err), "has_reading", b'Reading' in out if out else False)
PY"}

