#[derive(Debug, Clone)]
enum Opt {
    Help,
    Version,
    Keybinding,
    Fullscreen,
}

fn parse_args(args: &[String]) -> Result<(bool, Vec<String>, Vec<Opt>), ()> {
    let mut opts: Vec<Opt> = Vec::new();
    let mut files: Vec<String> = Vec::new();
    let mut seen_dashdash = false;
    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        if seen_dashdash {
            // positional only
            files.push(a.clone());
            i += 1;
            continue;
        }
        if a == "--" {
            seen_dashdash = true;
            i += 1;
            continue;
        }
        if a.starts_with("-") && a.len() > 1 {
            // Could be combined short flags or long flags
            if a.starts_with("--") {
                // long flag
                match a.as_str() {
                    "--help" => opts.push(Opt::Help),
                    "--version" => opts.push(Opt::Version),
                    "--key" | "--keybinding" => opts.push(Opt::Keybinding),
                    "--fullscreen" => opts.push(Opt::Fullscreen),
                    _ => return Err(()),
                }
                i += 1;
            } else {
                // short flags could be combined: -hfk etc.
                // Each char after '-' is a flag.
                // But also note: -f is fullscreen, -h help, -v version, -k key
                // There is no "-key" etc; "-key" should be invalid (we saw).
                // So we handle each char individually.
                let chars: Vec<char> = a[1..].chars().collect();
                for ch in chars {
                    match ch {
                        'h' => opts.push(Opt::Help),
                        'v' => opts.push(Opt::Version),
                        'k' => opts.push(Opt::Keybinding),
                        'f' => opts.push(Opt::Fullscreen),
                        _ => return Err(()),
                    }
                }
                i += 1;
            }
        } else if a.starts_with("-") && a.len() == 1 {
            // single "-"
            return Err(());
            // actually file "-" is invalid -> Could not open file -, but per tests single "-" is considered file not found, not invalid arguments.
            // Let's handle differently: single "-" should be treated as file positional, not flag.
            // However earlier tests showed ./executable - => Could not open file -
            // So "-" should be considered file.
            // We'll handle: if a == "-" then positional file
        } else {
            // positional
            files.push(a.clone());
            i += 1;
        }
    }
    // Special case: single "-" we already returned invalid; need to correct.
    // Let's redo handling for single "-" as file: We early returned invalid. Instead we should treat "-" as positional regardless of starts_with "-".
    // So adjust logic above: if a == "-" then files.push.

    // Now check for extra handling: we returned Err for invalid flags earlier, but need to differentiate single "-" case.
    // This function returns Err for invalid args; caller will print "Invalid arguments"

    // Handle fullscreen flag: multiple -f are allowed (duplicate)
    // Help/version/key have precedence: we will handle later

    let has_fullscreen = opts.iter().any(|o| matches!(o, Opt::Fullscreen));
    Ok((has_fullscreen, files, opts))
}

// Corrected parse that handles "-" as file
fn parse_args_correct(raw: &[String]) -> Result<(bool, Option<String>, bool, bool, bool), String> {
    // Returns (fullscreen, file, help, version, key)
    let mut fullscreen = false;
    let mut help = false;
    let mut version = false;
    let mut key = false;
    let mut files: Vec<String> = Vec::new();
    let mut seen_dashdash = false;
    let mut invalid = false;

    let mut i = 0;
    while i < raw.len() {
        let a = &raw[i];
        if seen_dashdash {
            files.push(a.clone());
            i+=1;
            continue;
        }
        if a == "--" {
            seen_dashdash = true;
            i+=1;
            continue;
        }
        if a == "-" {
            files.push(a.clone());
            i+=1;
            continue;
        }
        if a.starts_with("-") {
            if a.starts_with("--") {
                match a.as_str() {
                    "--help" => help = true,
                    "--version" => version = true,
                    "--key" | "--keybinding" => key = true,
                    "--fullscreen" => fullscreen = true,
                    _ => invalid = true,
                }
            } else {
                // short combined
                for ch in a[1..].chars() {
                    match ch {
                        'h' => help = true,
                        'v' => version = true,
                        'k' => key = true,
                        'f' => fullscreen = true,
                        _ => invalid = true,
                    }
                }
            }
            i+=1;
            continue;
        } else {
            files.push(a.clone());
            i+=1;
            continue;
        }
    }

    if invalid {
        return Err("Invalid arguments\n".to_string());
    }
    // Check file count: if help/version/key present, files may be ignored? But earlier we saw help with 2 extra files => Invalid, but with 1 extra file => still help (not invalid).
    // Let's see: help with 1 file -> still help (ignore file). But help with 2 files -> invalid.
    // Similarly -k with file -> help? Actually -k with file ignores file, but with 2 files => invalid? We saw -k a b => Invalid.
    // So rule: if help/version/key is true, we still validate files count? For help/version/key, they still check for too many positional arguments? Let's examine:
    // - help with 1 extra file -> ok (we saw ['./executable','--help', '/tmp/a'] => help ok)
    // - help with 2 extra files -> invalid (we saw)
    // So they allow at most 1 file even when help present? But help normally ignores file; but if there are >1 positional, it's considered invalid arguments.
    // Similarly for version/key.
    // For normal (no help/version/key), files should be 0 or 1; if >1 => invalid.
    // So unified rule: if files.len() > 1 => invalid, regardless of help/version/key presence. But if files.len()==1, it's allowed to have help/version/key and file is ignored.
    // Check that with -- terminator: same.
    // So check files.len() >1 => invalid

    if files.len() > 1 {
        return Err("Invalid arguments\n".to_string());
    }

    // If invalid previously, already returned

    // Determine file option
    let file_opt = if files.len() == 1 { Some(files[0].clone()) } else { None };

    Ok((fullscreen, file_opt, help, version, key))
}

