// Custom JSON parser that mimics nlohmann error messages
fn parse_json_nlohmann(s: &str) -> Result<serde_json::Value, String> {
    // We will try to use serde_json first for successful parsing.
    // If serde succeeds, we still need to ensure extra trailing data detection with nlohmann message.
    // For errors, we will attempt to translate serde error to nlohmann style.
    // But for better fidelity, we could implement our own lexer to generate nlohmann errors directly.
    // For now, attempt to intercept serde_json error and map.

    let mut parser = NlohmannParser::new(s);
    // Try to parse
    match parser.parse() {
        Ok(v) => {
            // Check for trailing data after parsing (nlohmann expects end of input)
            // Our parser should have already checked; but if we used custom parser, it will.
            // If we fallback to serde, we need to detect trailing.
            // For now, if parser succeeded but there is trailing non-whitespace, we need to produce error: "parse error at line X, column Y: syntax error while parsing value - ... expected end of input"
            // Our parser handles this.
            Ok(v)
        },
        Err(e) => Err(e),
    }
}

struct NlohmannParser<'a> {
    input: &'a [u8],
    pos: usize,
    line: usize,
    col: usize, // column is 1-indexed per nlohmann: column counts bytes? Actually column is char count?
    // Need to track line/col accurately.
}

impl<'a> NlohmannParser<'a> {
    fn new(s: &'a str) -> Self {
        Self { input: s.as_bytes(), pos: 0, line: 1, col: 1 }
    }

    fn peek(&self) -> Option<u8> {
        self.input.get(self.pos).copied()
    }
    fn peek_n(&self, n: usize) -> Option<u8> {
        self.input.get(self.pos + n).copied()
    }
    fn advance(&mut self) {
        if self.pos < self.input.len() {
            let c = self.input[self.pos];
            self.pos += 1;
            if c == b'\n' {
                self.line += 1;
                self.col = 1;
            } else {
                self.col += 1;
            }
        }
    }
    fn advance_by(&mut self, n: usize) {
        for _ in 0..n { self.advance(); }
    }
    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c == b' ' || c == b'\t' || c == b'\r' || c == b'\n' {
                self.advance();
            } else {
                break;
            }
        }
    }
    fn current_line_col(&self) -> (usize, usize) {
        (self.line, self.col)
    }
    fn byte_pos_to_line_col(&self, pos: usize) -> (usize, usize) {
        let mut line = 1;
        let mut col = 1;
        for i in 0..pos {
            if self.input[i] == b'\n' {
                line += 1;
                col = 1;
            } else {
                col += 1;
            }
        }
        (line, col)
    }
    fn error_at(&self, line: usize, col: usize, msg: String) -> String {
        format!("\n[json.exception.parse_error.101] parse error at line {}, column {}: {}\n", line, col, msg)
    }

    fn parse(&mut self) -> Result<serde_json::Value, String> {
        self.skip_whitespace();
        if self.pos >= self.input.len() {
            // Empty input
            return Err(self.error_at(1, 1, "attempting to parse an empty input; check that your input string or stream contains the expected JSON".to_string()));
        }
        let start_line = self.line;
        let start_col = self.col;
        let val = self.parse_value()?;
        self.skip_whitespace();
        if self.pos < self.input.len() {
            // Trailing data
            let (line, col) = self.current_line_col();
            // Need to see what kind of trailing error to produce.
            // Cases: "unexpected 'X'; expected end of input" or "invalid literal; last read: '...'"
            // Let's peek trailing bytes
            let remaining = &self.input[self.pos..];
            let preview = String::from_utf8_lossy(&remaining[..remaining.len().min(50)]).to_string();
            // Decide message based on first char
            let first = remaining[0];
            if first == b'{' || first == b'[' || first == b'"' || first == b't' || first == b'f' || first == b'n' || first == b'-' || first.is_ascii_digit() {
                // Unexpected value start?
                // For nlohmann, examples:
                // "{"a":1} trailing" => invalid literal; last read: '1} tra'; expected end of input
                // "{"a":1}\n{"b":2}" => unexpected '{'; expected end of input
                // "[]]" => unexpected ']'; expected end of input
                // "{}]" => unexpected ']'; expected end of input
                // "nullx" => invalid literal; last read: 'nullx'; expected end of input
                // "123abc" => invalid literal; last read: '123a'; expected end of input
                //("\"abc\" extra" => invalid literal; last read: '"abc" e'; expected end of input
                // Let's heuristic: if remaining starts with ']' or '}' then unexpected char, else invalid literal.
                if first == b']' || first == b'}' {
                    // unexpected
                    let ch = first as char;
                    return Err(self.error_at(line, col, format!("syntax error while parsing value - unexpected '{}'; expected end of input", ch)));
                } else if first == b'{' || first == b'[' || first == b'"' {
                    let ch = first as char;
                    return Err(self.error_at(line, col, format!("syntax error while parsing value - unexpected '{}'; expected end of input", ch)));
                } else {
                    // invalid literal with last read preview of up to 5 chars?
                    // nlohmann shows last read as first few chars of trailing, up to maybe 5-10 and includes preceding char?
                    // For "{"a":1} trailing" preview is " trailing", but last read is "'1} tra'" (5 chars starting from "1} tra" includes previous char before space?)
                    // Actually original for "{\"a\":1} trailing" gives last read: '1} tra' (includes '1' then '}',' ','t','r','a' -> 6 chars? Let's count: "1} tra" is 6 (1,}, ,t,r,a). For nullx, last read 'nullx' is full. For 123abc, '123a' is 4. For "\"abc\" extra", '"abc" e' is 7? Hmm.
                    // Let's look at nlohmann source: it likely captures last read as up to 10 chars or something.
                    // We can approximate: take up to 10 chars from pos, but if pos>0 include previous char? For simplicity, take substring of length 10 from pos, or up to next whitespace.
                    // For generic fallback, we can use: format!("syntax error while parsing value - invalid literal; last read: '{}'; expected end of input", snippet)
                    // snippet should be first up to 10 or until end.
                    let snippet_len = 10.min(remaining.len());
                    let snippet = String::from_utf8_lossy(&remaining[..snippet_len]).to_string();
                    // Escape single quotes? nlohmann uses single quotes around last read.
                    return Err(self.error_at(line, col, format!("syntax error while parsing value - invalid literal; last read: '{}'; expected end of input", snippet)));
                }
            } else {
                // For other like '\'', etc, invalid literal
                let snippet = String::from_utf8_lossy(&remaining[..remaining.len().min(10)]).to_string();
                return Err(self.error_at(line, col, format!("syntax error while parsing value - invalid literal; last read: '{}'; expected end of input", snippet)));
            }
        }
        Ok(val)
    }

    fn parse_value(&mut self) -> Result<serde_json::Value, String> {
