                return Err(self.error_at(line, col, format!("syntax error while parsing value - invalid string: control character U+{} ({}) must be escaped to \\u{} or {}; last read: '{}'", code_hex, match c { 0x00=>"NUL",0x01=>"SOH",0x09=>"HT",0x0A=>"LF",0x0D=>"CR", _=>ch_name }, code_hex, display, raw_snippet)));
            } else {
                out.push(c as char);
                self.advance();
            }
        }
    }

