                let snippet_len = (i+1).saturating_sub(start_pos).min(5);
                let snippet = String::from_utf8_lossy(&self.input[start_pos..start_pos+snippet_len]).to_string();
                // For "0.}" snippet "0.}"? Actually start 0., then } next char, snippet "0.}" includes }?
