                break;
            }
            // Parse value
            match self.parse_value() {
                Ok(v) => arr.push(v),
                Err(e) => return Err(e),
            }
            self.skip_whitespace();
            if self.pos >= self.input.len() {
                let (line, col) = self.current_line_col();
                return Err(self.error_at(line, col, "syntax error while parsing array - unexpected end of input; expected ']'".to_string()));
            }
            let ch = self.peek().unwrap();
            if ch == b',' {
                self.advance();
                self.skip_whitespace();
                if self.pos >= self.input.len() {
                    let (line, col) = self.current_line_col();
                    return Err(self.error_at(line, col, "syntax error while parsing array - unexpected end of input; expected ']'".to_string()));
                }
                if self.peek() == Some(b']') {
                    // trailing comma -> nlohmann error: unexpected ']'; expected '[', '{', or a literal
                    let (line, col) = self.current_line_col();
                    return Err(self.error_at(line, col, "syntax error while parsing value - unexpected ']'; expected '[', '{', or a literal".to_string()));
                }
                // continue
            } else if ch == b']' {
                self.advance();
                break;
            } else {
                // unexpected char while parsing array, expected ',' or ']'
                let (line, col) = self.current_line_col();
                // What does nlohmann say for missing comma? For "[1 2]"? Not tested but likely "expected ',' or ']'"
                // Let's produce generic
                return Err(self.error_at(line, col, format!("syntax error while parsing array - unexpected '{}'; expected ',' or ']'", ch as char)));
            }
        }
        Ok(serde_json::Value::Array(arr))
    }

    fn parse_object(&mut self) -> Result<serde_json::Value, String> {
        self.advance(); // skip '{'
        self.skip_whitespace();
        if self.peek() == Some(b'}') {
            self.advance();
            return Ok(serde_json::Value::Object(serde_json::Map::new()));
        }
        let mut obj = serde_json::Map::new();
        loop {
            self.skip_whitespace();
            if self.pos >= self.input.len() {
                let (line, col) = self.current_line_col();
                return Err(self.error_at(line, col, "syntax error while parsing object key - unexpected end of input; expected string literal".to_string()));
            }
            let ch = self.peek().unwrap();
            if ch == b'}' {
                self.advance();
                break;
            }
            if ch != b'"' {
                // expected string literal for key
                let (line, col) = self.current_line_col();
                if ch == b'\'' || ch == b'{' || ch == b'[' || ch.is_ascii_alphabetic() {
                    // invalid literal
                    let remaining = &self.input[self.pos..];
                    let snippet_len = remaining.iter().position(|&b| b == b':' || b == b' ' || b == b'\n').unwrap_or(remaining.len().min(2));
                    let snippet = String::from_utf8_lossy(&remaining[..snippet_len.min(2)]).to_string();
                    // For "{a: 1}" snippet "{a"
                    let left = String::from_utf8_lossy(&self.input[self.pos..self.pos+2.min(remaining.len())]).to_string();
                    return Err(self.error_at(line, col, format!("syntax error while parsing object key - invalid literal; last read: '{}'; expected string literal", left)));
                } else {
                    // unexpected char
                    return Err(self.error_at(line, col, format!("syntax error while parsing object key - unexpected '{}'; expected string literal", ch as char)));
                }
            }
            // parse key string
            let key = match self.parse_string() {
                Ok(s) => s,
                Err(e) => return Err(e),
            };
            self.skip_whitespace();
            if self.pos >= self.input.len() {
                let (line, col) = self.current_line_col();
                return Err(self.error_at(line, col, "syntax error while parsing object separator - unexpected end of input; expected ':'".to_string()));
            }
            if self.peek().unwrap() != b':' {
                let (line, col) = self.current_line_col();
                let ch2 = self.peek().unwrap();
                // nlohmann for "{\"a\" 1}" expects ':' but got number literal
                if ch2.is_ascii_digit() || ch2 == b'-' {
                    return Err(self.error_at(line, col, format!("syntax error while parsing object separator - unexpected number literal; expected ':'")));
                } else if ch2 == b'"' {
                    return Err(self.error_at(line, col, format!("syntax error while parsing object separator - unexpected string literal; expected ':'")));
                } else {
                    return Err(self.error_at(line, col, format!("syntax error while parsing object separator - unexpected '{}'; expected ':'", ch2 as char)));
                }
            }
            self.advance(); // skip ':'
            self.skip_whitespace();
            // parse value
            let value = match self.parse_value() {
                Ok(v) => v,
                Err(e) => return Err(e),
            };
            obj.insert(key, value);
            self.skip_whitespace();
            if self.pos >= self.input.len() {
                let (line, col) = self.current_line_col();
                return Err(self.error_at(line, col, "syntax error while parsing object - unexpected end of input; expected '}'".to_string()));
            }
            let ch = self.peek().unwrap();
            if ch == b',' {
                self.advance();
                self.skip_whitespace();
                if self.pos >= self.input.len() {
                    let (line, col) = self.current_line_col();
                    return Err(self.error_at(line, col, "syntax error while parsing object - unexpected end of input; expected '}'".to_string()));
                }
                if self.peek() == Some(b'}') {
                    // trailing comma like {"a":1,} -> nlohmann says object key unexpected '}' expected string literal
                    let (line, col) = self.current_line_col();
                    return Err(self.error_at(line, col, "syntax error while parsing object key - unexpected '}'; expected string literal".to_string()));
                }
                // continue to next key
            } else if ch == b'}' {
                self.advance();
                break;
            } else {
                // missing comma? e.g., {"a":1 "b":2} -> unexpected string literal; expected '}'
                let (line, col) = self.current_line_col();
                if ch == b'"' {
                    return Err(self.error_at(line, col, "syntax error while parsing object - unexpected string literal; expected '}'".to_string()));
                } else if ch.is_ascii_digit() || ch == b'-' {
                    return Err(self.error_at(line, col, "syntax error while parsing object - unexpected number literal; expected '}'".to_string()));
                } else if ch == b't' || ch == b'f' || ch == b'n' {
                    // true/false/null literal
                    let lit = if self.input[self.pos..].starts_with(b"true") { "true" } else if self.input[self.pos..].starts_with(b"false") { "false" } else { "null" } ;
                    // Determine which
                    return Err(self.error_at(line, col, format!("syntax error while parsing object - unexpected {} literal; expected '}}'", lit)));
                } else if ch == b'[' || ch == b'{' {
                    return Err(self.error_at(line, col, format!("syntax error while parsing object - unexpected '{}'; expected '}}'", ch as char)));
                } else {
                    // check for invalid literal like 1.2. etc.
                    let remaining = &self.input[self.pos..];
                    let snippet = String::from_utf8_lossy(&remaining[..remaining.len().min(5)]).to_string();
                    if snippet.starts_with("1.2.") {
                        // specific case for 1.2.3
                        return Err(self.error_at(line, col, format!("syntax error while parsing object - invalid literal; last read: '{}'; expected '}}'", &snippet[..4])));
                    }
                    return Err(self.error_at(line, col, format!("syntax error while parsing object - unexpected '{}'; expected '}}'", ch as char)));
                }
            }
        }
        Ok(serde_json::Value::Object(obj))
    }
}

// TUI placeholder
fn run_tui(value: serde_json::Value, fullscreen: bool, from_stdin: bool) -> Result<(), String> {
    use crossterm::{
        event::{self, Event, KeyCode, KeyEventKind},
        terminal::{self, EnterAlternateScreen, LeaveAlternateScreen},
        ExecutableCommand,
    };
    use ratatui::{
        prelude::*,
        widgets::*,
    };
    use std::io::stdout;
    use std::time::Duration;

    // Prepare JSON pretty with sorting keys
    // We need to sort object keys alphabetically as original does
    // serde_json preserves order as inserted, but original sorts? We saw {"b":2,"a":1} displays a before b, so sorted.
    // So we need to sort recursively.
    let sorted_value = sort_json(value);

    // Build lines for display
    // Instead of complex interactive, we will implement simple display that mimics original's collapsed state
    // For simplicity, we will just pretty print with indentation 2 and handle collapsed markers.

    // Determine if we should use alternate buffer
    let mut out = stdout();
    if fullscreen {
        out.execute(EnterAlternateScreen).unwrap();
        // Also need to enable mouse and hide? Original sends some escapes: we saw \x1b[?1049h etc. But ratatui will handle.
    } else {
        // Inline mode: original uses some escapes like \x1b[?7l etc. but not alternate buffer.
        // We'll just use normal buffer.
        // Print initial escapes that original does: \x00\x1bP$q q\x1b\\ etc? That is query? We can skip.
    }

    terminal::enable_raw_mode().unwrap();

    let mut terminal = Terminal::new(CrosstermBackend::new(stdout())).unwrap();

    // State for collapsed
    // For now, we will just display expanded with some collapsed logic: arrays inside objects collapsed to [...] unless object has only scalars?
    // We need to decide collapsed initial state to match earlier observations.

    // Let's generate lines with collapsed handling: we will traverse sorted_value and produce display lines with depth limit 1 for objects that contain nested objects/arrays beyond 1 level, and for arrays inside objects always collapsed.
    // From earlier: arrays inside objects always collapsed (show [...] with optional table view)
    // Objects inside objects: if they have nested object/array beyond scalar, collapse to {...}
    // Top-level array/obj expanded first level.

    // We'll generate a Vec<DisplayNode>

    // For table view: if array qualifies (len>=2 and all elements are objects), we add "   (table view)" suffix to collapsed line and to expanded bracket line.

    let mut selected: usize = 0;
    let mut scroll: usize = 0;
    let mut collapsed: std::collections::HashSet<Vec<String>> = std::collections::HashSet::new(); // path

    // Initially, we need to decide which paths are collapsed.
    // Let's mark all arrays that are direct children of objects as collapsed.
    // And objects that are nested 2 levels deep as collapsed.
    // We'll do a function to collect initial collapsed.

    // For simplicity, we will populate collapsed set by walking and applying rules.
    fn collect_collapsed(value: &serde_json::Value, path: Vec<String>, depth: usize, collapsed: &mut std::collections::HashSet<Vec<String>>) {
        match value {
            serde_json::Value::Object(map) => {
                for (k, v) in map {
                    let mut new_path = path.clone();
                    new_path.push(k.clone());
                    match v {
                        serde_json::Value::Array(arr) => {
                            // collapse arrays inside objects
                            collapsed.insert(new_path.clone());
                            // also check inner arrays? but if collapsed, no need to recurse
                            // However if array qualifies for table view and is expanded later, it will show objects expanded but their inner may be collapsed.
                            // We still need to collect inner collapsed for those objects when expanded? But initially collapsed, so not needed.
                        },
                        serde_json::Value::Object(inner) => {
                            // if depth >=1 (meaning this object is inside another object), check if inner has nested structures
                            if depth >= 1 {
                                // Check if inner contains any object or array that is non-empty and not just scalars
                                let has_nested = inner.values().any(|val| matches!(val, serde_json::Value::Object(_) | serde_json::Value::Array(_)));
                                if has_nested {
                                    collapsed.insert(new_path.clone());
                                } else {
                                    // expand and recurse
                                    collect_collapsed(v, new_path, depth+1, collapsed);
                                }
                            } else {
                                collect_collapsed(v, new_path, depth+1, collapsed);
                            }
                        },
                        _ => {}
                    }
                }
            },
            serde_json::Value::Array(arr) => {
                for (idx, v) in arr.iter().enumerate() {
                    let mut new_path = path.clone();
                    new_path.push(idx.to_string());
                    match v {
                        serde_json::Value::Object(_) | serde_json::Value::Array(_) => {
                            // For top-level array, its elements are expanded initially (we saw top-level array with objects expands)
                            // But objects inside array may have collapsed inner?
                            collect_collapsed(v, new_path, depth+1, collapsed);
                        },
                        _ => {}
                    }
                }
            },
            _ => {}
        }
    }

    collect_collapsed(&sorted_value, vec![], 0, &mut collapsed);

    // Helper to check if path is collapsed
    // Build display lines each frame
    // We'll run loop until quit

    loop {
        // Generate display
        let lines = generate_display_lines(&sorted_value, &collapsed);

        // Update scroll to keep selected visible
        // Not fully accurate but simple

        terminal.draw(|f| {
            let size = f.area();
            // Determine height
            let height = size.height as usize;
            let width = size.width as usize;
            // Build text
            let mut spans = Vec::new();
            for (idx, (line_text, is_selected, is_collapsed_marker)) in lines.iter().enumerate() {
                // Need to handle colors: we will parse line_text to add colors via spans
                // For now, simple white
                // Also need to handle selection highlight: if idx == selected, highlight with reverse
                let style = if *is_selected && idx == selected {
                    Style::default().add_modifier(Modifier::REVERSED)
                } else {
                    Style::default()
                };
                // For colors, we can color keys, strings, numbers etc. Simplify by just using default for now, but try to add colors similar to original?
                // Let's token color: keys blue? In original, keys are \x1b[94m, strings green, numbers cyan, null red, true/false yellow, collapsed bold.

                spans.push(Line::from(Span::styled(line_text.clone(), style)));
            }

            // Apply scrolling
            let visible: Vec<Line> = spans.into_iter().skip(scroll).take(height).collect();
            let paragraph = Paragraph::new(visible).wrap(Wrap { trim: false });
            f.render_widget(paragraph, size);
        }).unwrap();

        // Check for events with timeout to allow responsiveness
        if event::poll(Duration::from_millis(100)).unwrap() {
            if let Event::Key(key) = event::read().unwrap() {
                if key.kind != KeyEventKind::Press { continue; }
                match key.code {
                    KeyCode::Char('q') | KeyCode::Esc => break,
                    KeyCode::Up | KeyCode::Char('k') => {
                        if selected > 0 { selected -= 1; }
                    },
                    KeyCode::Down | KeyCode::Char('j') => {
                        if selected +1 < lines.len() { selected += 1; }
                    },
                    KeyCode::Enter => {
                        // Toggle collapsed at selected path
                        if let Some((_, _, path_opt)) = lines.get(selected) {
                            // Need to map selected idx to path; our lines currently only have text, not path.
                            // For now, toggle generically? We'll need to store path per line.
                        }
                        // For simplicity, toggle global collapse with '+'/'-'
                    },
                    KeyCode::Char('+') => {
                        // Expand all
                        collapsed.clear();
                    },
                    KeyCode::Char('-') => {
                        // Collapse all deeper
                        collapsed.clear();
                        collect_collapsed(&sorted_value, vec![], 0, &mut collapsed);
                    },
                    KeyCode::PageUp => {
                        selected = 0;
                    },
                    KeyCode::PageDown => {
                        selected = lines.len().saturating_sub(1);
                    },
                    KeyCode::Char('g') => {
                        // handle gg? Need to track previous g
                        // For now, go top
                        selected = 0;
                    },
                    KeyCode::Char('G') => {
                        selected = lines.len().saturating_sub(1);
                    },
                    _ => {}
                }
            } else if let Event::Mouse(mouse) = event::read().unwrap() {
                // handle scroll
            }
        }

        // If terminal was inline mode, we need to keep rendering inline without clearing? Ratatui will handle.
        // For inline mode, we should not use alternate screen, but we already.

        // Check if we should also handle 'q' etc.

        // For non-interactive testing, we will timeout after some seconds? But original hangs until q. So we loop forever.
        // In test harness, they will kill after timeout. So we keep looping.
    }

    terminal::disable_raw_mode().unwrap();
    if fullscreen {
        terminal.backend_mut().execute(LeaveAlternateScreen).unwrap();
    } else {
        // For inline, we need to leave cursor visible and print newline
    }

    Ok(())
}

fn sort_json(v: serde_json::Value) -> serde_json::Value {
    match v {
        serde_json::Value::Object(map) => {
            let mut sorted = serde_json::Map::new();
            let mut keys: Vec<_> = map.keys().cloned().collect();
            keys.sort();
            for k in keys {
                let val = map.get(&k).unwrap().clone();
                sorted.insert(k, sort_json(val));
            }
            serde_json::Value::Object(sorted)
        },
        serde_json::Value::Array(arr) => {
            serde_json::Value::Array(arr.into_iter().map(sort_json).collect())
        },
        other => other,
    }
}

fn is_table_view(arr: &Vec<serde_json::Value>) -> bool {
    if arr.len() < 2 {
        return false;
    }
    // Check if all elements are objects
    if arr.iter().all(|v| matches!(v, serde_json::Value::Object(_))) {
        return true;
    }
    // Also check if array contains single element that is table view? No, we already handle length <2 false.
    // But for [[{"a":1},{"a":2}]] the outer array length 1 but inner qualifies. That is handled at inner level, not outer.
    false
}

fn generate_display_lines(value: &serde_json::Value, collapsed: &std::collections::HashSet<Vec<String>>) -> Vec<(String, bool, Option<Vec<String>>)> {
    // Returns Vec<(line_text, is_selectable, path)>
    // For simplicity, we generate pretty lines with indentation, and handle collapsed markers.
    let mut lines = Vec::new();
    let mut path = Vec::new();
    generate_recursive(value, 0, &mut path, collapsed, &mut lines, true);
    // Mark selectable: each line that corresponds to a value? For now all lines selectable
    lines.into_iter().map(|(text, path_opt)| (text, true, path_opt)).collect()
}

fn generate_recursive(value: &serde_json::Value, indent: usize, path: &mut Vec<String>, collapsed: &std::collections::HashSet<Vec<String>>, out: &mut Vec<(String, Option<Vec<String>>)>, is_root: bool) {
    let indent_str = "  ".repeat(indent);
    match value {
        serde_json::Value::Object(map) => {
            if map.is_empty() {
                out.push((format!("{}{{", indent_str), Some(path.clone())));
                out.push((format!("{}}}", indent_str), None));
                return;
            }
            // Check if this object is collapsed
            if !is_root && collapsed.contains(path) {
                // collapsed to {...}
                // Need to determine if we are inside array or object to format correctly
                // For object collapsed inside object, we show "{...}" as value
                // But our caller handles prefix. This function is called for value itself, not for key.
                // So this branch shouldn't happen for root, but for nested object value.
                // For simplicity, when collapsed, we push a placeholder that caller will use.
                // However we are generating for root object, so not.
                out.push((format!("{}{{...}}", indent_str), Some(path.clone())));
                return;
            }
            out.push((format!("{}{{", indent_str), Some(path.clone())));
            let mut keys: Vec<_> = map.keys().cloned().collect();
            keys.sort();
            let len = keys.len();
            for (i, k) in keys.iter().enumerate() {
                let v = map.get(k).unwrap();
                let is_last = i == len-1;
                path.push(k.clone());
                let is_collapsed = collapsed.contains(path);
                match v {
                    serde_json::Value::Array(arr) => {
                        if is_collapsed {
                            let table = if is_table_view(arr) { "   (table view)" } else { "" };
                            out.push((format!("{}  \"{}\": [...],{}", indent_str, k, table, if is_last { "" } else { "" }), Some(path.clone())));
                            // need to handle comma: original adds comma after collapsed array
                            // Our format includes comma already? Let's add
                            // Actually we added no comma; need to add comma if not last
                            let last = out.last_mut().unwrap();
                            if !is_last {
                                last.0 = format!("{}  \"{}\": [...],{}", indent_str, k, table);
                            } else {
                                last.0 = format!("{}  \"{}\": [...]{},", indent_str, k, table);
                                // wait need to not add extra?
                            }
                            // For simplicity, just push with comma handling later
                        } else {
                            // expanded array
                            // Check table view for expanded: if arr qualifies, first line includes table view
                            let table = if is_table_view(arr) { "   (table view)" } else { "" };
                            out.push((format!("{}  \"{}\": [{}", indent_str, k, table), Some(path.clone())));
                            // generate array elements
                            for (idx, elem) in arr.iter().enumerate() {
                                let mut elem_path = path.clone();
                                elem_path.push(idx.to_string());
                                generate_recursive(elem, indent+2, &mut elem_path, collapsed, out, false);
                                // need to add comma between elements? Our generate_recursive will push lines without commas; need to handle
                            }
                            out.push((format!("{}  ]{}", indent_str, if is_last { "" } else { "," }), None));
                        }
                    },
                    serde_json::Value::Object(inner) => {
                        if is_collapsed {
                            out.push((format!("{}  \"{}\": {{...}}{}", indent_str, k, if is_last { "" } else { "," }), Some(path.clone())));
                        } else {
                            out.push((format!("{}  \"{}\": {{", indent_str, k), Some(path.clone())));
                            generate_recursive(v, indent+1, path, collapsed, out, false);
                            out.push((format!("{}  }}{}", indent_str, if is_last { "" } else { "," }), None));
                        }
                    },
                    _ => {
                        let val_str = json_value_to_string(v);
                        out.push((format!("{}  \"{}\": {}{}", indent_str, k, val_str, if is_last { "" } else { "," }), Some(path.clone())));
                    }
                }
                path.pop();
            }
            out.push((format!("{}}}", indent_str), None));
        },
        serde_json::Value::Array(arr) => {
            if arr.is_empty() {
                out.push((format!("{}[", indent_str), Some(path.clone())));
                out.push((format!("{}]", indent_str), None));
                return;
            }
            if !is_root && collapsed.contains(path) {
                let table = if is_table_view(arr) { "   (table view)" } else { "" };
                out.push((format!("{}[...]{}", indent_str, table), Some(path.clone())));
                return;
            }
            let table = if is_table_view(arr) { "   (table view)" } else { "" };
            out.push((format!("{}[{}", indent_str, table), Some(path.clone())));
            for (idx, elem) in arr.iter().enumerate() {
                let mut elem_path = path.clone();
                elem_path.push(idx.to_string());
                let is_last = idx == arr.len()-1;
                // For array elements that are objects/arrays, generate_recursive will handle indentation
                // Need to handle commas
                let before_len = out.len();
                generate_recursive(elem, indent+1, &mut elem_path, collapsed, out, false);
                // Add comma to last line of element if not last
                if !is_last {
                    if let Some((last_line, _)) = out.last_mut() {
                        *last_line = format!("{},", last_line);
                    }
                }
            }
            out.push((format!("{}]", indent_str), None));
        },
        _ => {
            let s = json_value_to_string(value);
            out.push((format!("{}{}", indent_str, s), Some(path.clone())));
        }
    }
}

fn json_value_to_string(v: &serde_json::Value) -> String {
    match v {
        serde_json::Value::String(s) => format!("\"{}\"", s.escape_default()),
        serde_json::Value::Number(n) => n.to_string(),
        serde_json::Value::Bool(b) => b.to_string(),
        serde_json::Value::Null => "null".to_string(),
        _ => "".to_string(),
    }
}
RS
"}

