// Custom JSON parser that mimics nlohmann error messages
fn parse_json_nlohmann(s: &str) -> Result<serde_json::Value, String> {
    // We will try to use serde_json first for successful parsing.
    // If serde succeeds, we still need to ensure extra trailing data detection with nlohmann message.
    // For errors, we will attempt to translate serde error to nlohmann style.
    // But for better fidelity, we could implement our own lexer to generate nlohmann errors directly.
    // For now, attempt to intercept serde_json error and map.

    let mut parser = NlohmannParser::new(s);
    // Try to parse
    match parser.parse() {
        Ok(v) => {
            // Check for trailing data after parsing (nlohmann expects end of input)
            // Our parser should have already checked; but if we used custom parser, it will.
            // If we fallback to serde, we need to detect trailing.
            // For now, if parser succeeded but there is trailing non-whitespace, we need to produce error: "parse error at line X, column Y: syntax error while parsing value - ... expected end of input"
            // Our parser handles this.
            Ok(v)
        },
        Err(e) => Err(e),
    }
}

struct NlohmannParser<'a> {
    input: &'a [u8],
    pos: usize,
    line: usize,
    col: usize, // column is 1-indexed per nlohmann: column counts bytes? Actually column is char count?
    // Need to track line/col accurately.
}

impl<'a> NlohmannParser<'a> {
    fn new(s: &'a str) -> Self {
        Self { input: s.as_bytes(), pos: 0, line: 1, col: 1 }
    }

    fn peek(&self) -> Option<u8> {
        self.input.get(self.pos).copied()
    }
    fn peek_n(&self, n: usize) -> Option<u8> {
        self.input.get(self.pos + n).copied()
    }
    fn advance(&mut self) {
        if self.pos < self.input.len() {
            let c = self.input[self.pos];
            self.pos += 1;
            if c == b'\n' {
                self.line += 1;
                self.col = 1;
            } else {
                self.col += 1;
            }
        }
    }
    fn advance_by(&mut self, n: usize) {
        for _ in 0..n { self.advance(); }
    }
    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c == b' ' || c == b'\t' || c == b'\r' || c == b'\n' {
                self.advance();
            } else {
                break;
            }
        }
    }
    fn current_line_col(&self) -> (usize, usize) {
        (self.line, self.col)
    }
    fn byte_pos_to_line_col(&self, pos: usize) -> (usize, usize) {
        let mut line = 1;
        let mut col = 1;
        for i in 0..pos {
            if self.input[i] == b'\n' {
                line += 1;
                col = 1;
            } else {
                col += 1;
            }
        }
        (line, col)
    }
    fn error_at(&self, line: usize, col: usize, msg: String) -> String {
        format!("\n[json.exception.parse_error.101] parse error at line {}, column {}: {}\n", line, col, msg)
    }

    fn parse(&mut self) -> Result<serde_json::Value, String> {
